IEnumerator Run(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var s=h.Sandbox;var m=s.PauseMenu;s.Clock.Paused=true;s.Persistence.Automatic=false;h.Input.Cancel();h.GetComponent<GameplayHudWorkspace>().Construction();yield return new WaitForSecondsRealtime(.4f);var field=typeof(SingleMapPersistence).GetField("store",BindingFlags.Instance|BindingFlags.NonPublic);var original=field.GetValue(s.Persistence);string stamp=s.Persistence.LastSavedUtc;
